    public record PendingPermission(
            String permissionId, long revision, String toolName, Map<String, Object> arguments,
            WorkspaceIdentity workspace, Risk risk, String status) {
        public PendingPermission {
            requireText(permissionId, "permissionId");
            if (revision < 0) throw new IllegalArgumentException("permission revision must be non-negative");
            requireText(toolName, "toolName");
            arguments = Map.copyOf(arguments);
            if (workspace == null || risk == null || !"pending".equals(status)) {
                throw new IllegalArgumentException("pending permission state is invalid");
            }
        }
    }

    public record WorkspaceIdentity(String workspaceId, long generation) {
        public WorkspaceIdentity {
            requireText(workspaceId, "workspaceId");
            if (generation < 0) throw new IllegalArgumentException("workspace generation must be non-negative");
        }
    }

    public record Risk(String level, String ruleId) {
        public Risk {
            if (!List.of("low", "medium", "high").contains(level)) {
                throw new IllegalArgumentException("permission risk level is invalid");
            }
            requireText(ruleId, "risk ruleId");
        }
    }

    public enum Status { RUNNING, CANCELLING, PAUSED }

    private static void requireText(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
    }
}
